using System;using System.Collections.Generic;using System.Diagnostics;using System.Globalization;using System.IO;using System.IO.Compression;using System.Linq;using System.Security.Cryptography;using System.Text;using Microsoft.ML.OnnxRuntime;using Microsoft.VisualBasic.FileIO;
namespace PdfRasterProbe{
internal static class H1D9D1CResamplerParityProbe{
const int S=224,P=22;const double TNO=.1169927716255188,TYES=.7979831695556641;static readonly float[] Mean={.485f,.456f,.406f},Std={.229f,.224f,.225f};static readonly UTF8Encoding U=new UTF8Encoding(false);
internal static int Run(string[]a){if(a.Length!=6){Console.Error.WriteLine("Uso: --h1d9d1c-resampler-parity <onnx> <reference.csv> <development-assets.csv> <holdout-assets.csv> <output>");return 2;}try{return Execute(a);}catch(Exception e){Console.Error.WriteLine("H1D9D1C | Resultado=H1D9D1C NO APROBADO\n"+e);return 1;}}
static int Execute(string[]a){var refs=Read(a[2]).Select((r,i)=>new R{I=i,Sha=r["Sha256"],Cohort=r["Cohort"],Group=r["GroupId"],SW=I(r["SourceWidth"]),SH=I(r["SourceHeight"]),SourceHash=r["SourceRgbSha256"],RW=I(r["ResizedWidth"]),RH=I(r["ResizedHeight"]),L=I(r["Left"]),T=I(r["Top"]),ResizeHash=r["ResizedRgbSha256"],TargetHash=r["TargetRgbSha256"],TensorHash=r["TensorSha256"],Prob=D(r["PFactura"]),Pred=r["Pred050"],Zone=r["Zona"]}).ToList();var assets=Assets(a[3],"DEVELOPMENT").Concat(Assets(a[4],"HOLDOUT")).ToDictionary(x=>x.Sha,StringComparer.OrdinalIgnoreCase);var o=Path.GetFullPath(a[5]);var tmp=Path.Combine(o,"python-resized.tmp");var targetBin=Path.Combine(o,"target-rgb.tmp.bin");var tensorBin=Path.Combine(o,"tensor.tmp.bin");if(refs.Count!=80||assets.Count!=80||!Directory.Exists(tmp))throw new InvalidDataException("Referencias incompletas.");
var samples=new List<X>();foreach(var r in refs){var total=Stopwatch.StartNew();int w,h;var decode=Stopwatch.StartNew();var src=H1D9D1BDirectRgbProbe.DecodeRgbDirect(assets[r.Sha].Path,out w,out h);decode.Stop();var scale=Math.Min((double)S/w,(double)S/h);var rw=Math.Max(1,(int)Math.Round(w*scale,MidpointRounding.ToEven));var rh=Math.Max(1,(int)Math.Round(h*scale,MidpointRounding.ToEven));var l=(S-rw)/2;var t=(S-rh)/2;var hor=Stopwatch.StartNew();var hbuf=Horizontal(src,w,h,rw);hor.Stop();var ver=Stopwatch.StartNew();var resized=Vertical(hbuf,rw,h,rh);ver.Stop();var box=Stopwatch.StartNew();var target=Enumerable.Repeat((byte)255,S*S*3).ToArray();for(var y=0;y<rh;y++)Buffer.BlockCopy(resized,y*rw*3,target,((t+y)*S+l)*3,rw*3);box.Stop();total.Stop();var ex=Gzip(Path.Combine(tmp,r.Sha+".rgb.gz"));samples.Add(new X{R=r,W=w,H=h,RW=rw,RH=rh,L=l,T=t,SourceHash=Hash(src),ResizeHash=Hash(resized),TargetHash=Hash(target),ResizeDiff=Diff(ex,resized),Target=target,Decode=decode.Elapsed.TotalMilliseconds,Hor=hor.Elapsed.TotalMilliseconds,Ver=ver.Elapsed.TotalMilliseconds,Box=box.Elapsed.TotalMilliseconds,Total=total.Elapsed.TotalMilliseconds});}
var source=samples.Count(x=>x.SourceHash==x.R.SourceHash&&x.W==x.R.SW&&x.H==x.R.SH);WriteSource(o,samples);if(source!=80)return Stop(o,tmp,targetBin,tensorBin,"SOURCE_RGB",source,0,0,samples);
var dims=samples.Count(x=>x.RW==x.R.RW&&x.RH==x.R.RH&&x.L==x.R.L&&x.T==x.R.T);WriteDims(o,samples);if(dims!=80)return Stop(o,tmp,targetBin,tensorBin,"DIMENSIONS_OFFSETS",source,dims,0,samples);
var resizedEqual=samples.Count(x=>x.ResizeHash==x.R.ResizeHash);WriteResize(o,samples);if(resizedEqual!=80){WriteCoefficientDiagnostics(o,samples.First(x=>x.ResizeHash!=x.R.ResizeHash));return Stop(o,tmp,targetBin,tensorBin,"RESIZED_RGB",source,dims,resizedEqual,samples);}
var targets=File.ReadAllBytes(targetBin);foreach(var x in samples)x.TargetDiff=Diff(Slice(targets,x.R.I*S*S*3,S*S*3),x.Target);var targetEqual=samples.Count(x=>x.TargetHash==x.R.TargetHash);WriteTarget(o,samples);if(targetEqual!=80)return Stop(o,tmp,targetBin,tensorBin,"TARGET_RGB",source,dims,resizedEqual,samples);
var tensors=File.ReadAllBytes(tensorBin);foreach(var x in samples){var n=Stopwatch.StartNew();x.Tensor=Normalize(x.Target);n.Stop();x.Norm=n.Elapsed.TotalMilliseconds;x.TensorDiff=Diff(Floats(tensors,x.R.I*S*S*3*4,S*S*3),x.Tensor);}var tensorMax=samples.Max(x=>x.TensorDiff.Max);WriteTensor(o,samples);if(tensorMax>.000001)return Stop(o,tmp,targetBin,tensorBin,"TENSOR",source,dims,resizedEqual,samples);
using(var session=new InferenceSession(Path.GetFullPath(a[1]),new SessionOptions()))foreach(var x in samples){var q=Stopwatch.StartNew();x.PF=Infer(session,x.Tensor);q.Stop();x.Onnx=q.Elapsed.TotalMilliseconds;}WriteOnnx(o,samples);var ds=samples.Select(x=>Math.Abs(x.PF-x.R.Prob)).OrderBy(x=>x).ToList();var pred=samples.Count(x=>Pred(x.PF)==x.R.Pred);var zones=samples.Count(x=>Zone(x.PF)==x.R.Zone);var hold=samples.Where(x=>x.R.Cohort=="HOLDOUT").ToList();var files=hold.Count(x=>Pred(x.PF)==assets[x.R.Sha].Label);var groups=hold.GroupBy(x=>x.R.Group).Count(g=>Pred((float)g.Average(x=>x.PF))==assets[g.First().R.Sha].Label);var danger=hold.Count(x=>(assets[x.R.Sha].Label=="FACTURA"&&Zone(x.PF)=="NO_FACTURA_FUERTE")||(assets[x.R.Sha].Label=="NO_FACTURA"&&Zone(x.PF)=="FACTURA_FUERTE"));var ok=pred==80&&zones==80&&Pct(ds,.95)<=.00001&&ds.Last()<=.00005&&files==10&&groups==5&&danger==0;WriteReports(o,samples,source,dims,resizedEqual,targetEqual,tensorMax,pred,zones,ds,files,groups,danger,ok);Clean(tmp,targetBin,tensorBin);Console.WriteLine("H1D9D1C | Resultado="+(ok?"H1D9D1C APROBADO":"H1D9D1C NO APROBADO")+" | Source=80 | Dimensions=80 | Resized=80 | Target=80 | Pred="+pred+" | Zones="+zones);return ok?0:1;}
static byte[] Horizontal(byte[]i,int iw,int ih,int ow){var t=Coeffs(iw,ow);var o=new byte[ow*ih*3];for(int y=0;y<ih;y++)for(int x=0;x<ow;x++)for(int c=0;c<3;c++){long z=1<<(P-1);for(int k=0;k<t[x].V.Length;k++)z+=i[(y*iw+t[x].Start+k)*3+c]*(long)t[x].V[k];o[(y*ow+x)*3+c]=Clip(z>>P);}return o;}
static byte[] Vertical(byte[]i,int iw,int ih,int oh){var t=Coeffs(ih,oh);var o=new byte[iw*oh*3];for(int y=0;y<oh;y++)for(int x=0;x<iw;x++)for(int c=0;c<3;c++){long z=1<<(P-1);for(int k=0;k<t[y].V.Length;k++)z+=i[((t[y].Start+k)*iw+x)*3+c]*(long)t[y].V[k];o[(y*iw+x)*3+c]=Clip(z>>P);}return o;}
static C[] Coeffs(int input,int output){var scale=(double)input/output;var fs=Math.Max(1,scale);var support=2*fs;var r=new C[output];for(int xx=0;xx<output;xx++){var center=(xx+.5)*scale;var min=Math.Max(0,(int)(center-support+.5));var max=Math.Min(input,(int)(center+support+.5));var d=new double[max-min];double sum=0;for(int k=0;k<d.Length;k++){d[k]=Cubic((k+min-center+.5)/fs);sum+=d[k];}for(int k=0;k<d.Length;k++)d[k]/=sum;r[xx]=new C{Start=min,D=d,V=d.Select(v=>v<0?(int)(-.5+v*(1<<P)):(int)(.5+v*(1<<P))).ToArray()};}return r;}
static double Cubic(double x){x=Math.Abs(x);return x<1?((1.5*x-2.5)*x*x+1):x<2?(((-.5*x+2.5)*x-4)*x+2):0;}static byte Clip(long x){return x<0?(byte)0:x>255?(byte)255:(byte)x;}
static void WriteCoefficientDiagnostics(string o,X x){var lines=new List<string>{"Axis,OutputIndex,InputSize,OutputSize,Scale,FilterScale,Support,Center,XMin,CoefficientCount,DoubleCoefficients,FixedCoefficients"};foreach(var q in new[]{new{A="H",N=x.W,O=x.RW},new{A="V",N=x.H,O=x.RH}}){var tab=Coeffs(q.N,q.O);foreach(var ix in new[]{0,q.O/2,q.O-1}){var c=tab[ix];var scale=(double)q.N/q.O;var fs=Math.Max(1,scale);lines.Add(string.Join(",",q.A,ix,q.N,q.O,F(scale),F(fs),F(2*fs),F((ix+.5)*scale),c.Start,c.V.Length,"\""+string.Join("|",c.D.Select(F))+"\"","\""+string.Join("|",c.V)+"\""));}}Write(Path.Combine(o,"coefficient-diagnostics.csv"),lines);Write(Path.Combine(o,"pixel-accumulator-diagnostics.csv"),"Status\nRESIZED_RGB_FAILED_COEFFICIENT_AUDIT_CAPTURED\n");}
static int Stop(string o,string tmp,string tb,string xb,string stage,int src,int dims,int resized,List<X>x){Write(Path.Combine(o,"target-rgb-parity.csv"),"Status\nNOT_EXECUTED_"+stage+"\n");Write(Path.Combine(o,"parity-metrics.md"),"# H1D9D1C — Métricas\n\nDetenido en "+stage+". Source="+src+"/80; dimensiones="+dims+"/80; resized="+resized+"/80.\n");Write(Path.Combine(o,"resumen.md"),"# H1D9D1C — Resultado\n\n`H1D9D1C NO APROBADO`\n\nDetenido exactamente en "+stage+".\n");Write(Path.Combine(o,"parity-manifest.json"),"{\n \"milestone\":\"H1D9D1C\",\"status\":\"NO_APROBADO\",\"stopped_at\":\""+stage+"\",\"source_equal\":"+src+",\"dimensions_equal\":"+dims+",\"resized_equal\":"+resized+",\"negative_rounding_fixed\":true,\"training_performed\":false,\"threshold_tuning_performed\":false,\"product_modified\":false\n}\n");Clean(tmp,tb,xb);return 1;}
static void WriteSource(string o,List<X>x){Write(Path.Combine(o,"source-rgb-parity.csv"),new[]{"Sha256,Cohort,PythonHash,CSharpHash,Equal"}.Concat(x.Select(v=>string.Join(",",v.R.Sha,v.R.Cohort,v.R.SourceHash,v.SourceHash,B(v.R.SourceHash==v.SourceHash)))));}static void WriteDims(string o,List<X>x){Write(Path.Combine(o,"resize-dimensions-parity.csv"),new[]{"Sha256,PythonWidth,CSharpWidth,PythonHeight,CSharpHeight,PythonLeft,CSharpLeft,PythonTop,CSharpTop,Equal"}.Concat(x.Select(v=>string.Join(",",v.R.Sha,v.R.RW,v.RW,v.R.RH,v.RH,v.R.L,v.L,v.R.T,v.T,B(v.RW==v.R.RW&&v.RH==v.R.RH&&v.L==v.R.L&&v.T==v.R.T)))));}static void WriteResize(string o,List<X>x){Write(Path.Combine(o,"resized-rgb-parity.csv"),new[]{"Sha256,Cohort,PythonHash,CSharpHash,Equal,DifferentBytes,MaeRgb,MaxDelta,FirstByte,Pixel,Channel,PythonValue,CSharpValue"}.Concat(x.Select(v=>string.Join(",",v.R.Sha,v.R.Cohort,v.R.ResizeHash,v.ResizeHash,B(v.R.ResizeHash==v.ResizeHash),v.ResizeDiff.N,F(v.ResizeDiff.Mae),F(v.ResizeDiff.Max),v.ResizeDiff.First,v.ResizeDiff.First<0?-1:v.ResizeDiff.First/3,v.ResizeDiff.First<0?"":new[]{"R","G","B"}[v.ResizeDiff.First%3],v.ResizeDiff.E,v.ResizeDiff.A))));}
static void WriteTarget(string o,List<X>x){Write(Path.Combine(o,"target-rgb-parity.csv"),new[]{"Sha256,Cohort,PythonHash,CSharpHash,Equal,DifferentBytes,MaeRgb,MaxDelta"}.Concat(x.Select(v=>string.Join(",",v.R.Sha,v.R.Cohort,v.R.TargetHash,v.TargetHash,B(v.R.TargetHash==v.TargetHash),v.TargetDiff.N,F(v.TargetDiff.Mae),F(v.TargetDiff.Max)))));}static void WriteTensor(string o,List<X>x){Write(Path.Combine(o,"tensor-parity.csv"),new[]{"Sha256,PythonHash,CSharpHash,DifferentFloats,MeanAbsDelta,MaxAbsDelta"}.Concat(x.Select(v=>string.Join(",",v.R.Sha,v.R.TensorHash,Hash(Bytes(v.Tensor)),v.TensorDiff.N,F(v.TensorDiff.Mae),F(v.TensorDiff.Max)))));}static void WriteOnnx(string o,List<X>x){Write(Path.Combine(o,"onnx-parity.csv"),new[]{"Sha256,Cohort,PythonPFactura,CSharpPFactura,AbsDelta,PredEqual,ZoneEqual"}.Concat(x.Select(v=>string.Join(",",v.R.Sha,v.R.Cohort,F(v.R.Prob),F(v.PF),F(Math.Abs(v.R.Prob-v.PF)),B(v.R.Pred==Pred(v.PF)),B(v.R.Zone==Zone(v.PF))))));}
static void WriteReports(string o,List<X>x,int src,int dims,int resize,int target,double tm,int pred,int zones,List<double>d,int files,int groups,int danger,bool ok){var metrics="# H1D9D1C — Métricas\n\n- Source RGB: "+src+"/80; dimensiones/offsets: "+dims+"/80; resized: "+resize+"/80; target: "+target+"/80.\n- Tensor máximo: "+F(tm)+". Pred050: "+pred+"/80; zonas: "+zones+"/80.\n- PFactura delta media "+F(d.Average())+", P95 "+F(Pct(d,.95))+", máximo "+F(d.Last())+".\n- HOLDOUT "+files+"/10 archivos, "+groups+"/5 grupos, "+danger+" errores fuertes.\n- Decode ms: "+Stats(x.Select(v=>v.Decode))+". Horizontal: "+Stats(x.Select(v=>v.Hor))+". Vertical: "+Stats(x.Select(v=>v.Ver))+". Letterbox: "+Stats(x.Select(v=>v.Box))+". Normalización: "+Stats(x.Select(v=>v.Norm))+". ONNX: "+Stats(x.Select(v=>v.Onnx))+". Total: "+Stats(x.Select(v=>v.Decode+v.Hor+v.Ver+v.Box+v.Norm+v.Onnx))+".\n";Write(Path.Combine(o,"parity-metrics.md"),metrics);Write(Path.Combine(o,"resumen.md"),"# H1D9D1C — Resultado\n\n`H1D9D1C "+(ok?"APROBADO":"NO APROBADO")+"`\n\n"+metrics.Substring(metrics.IndexOf("- Source"))+"\n");Write(Path.Combine(o,"parity-manifest.json"),"{\n\"milestone\":\"H1D9D1C\",\"status\":\""+(ok?"APROBADO":"NO_APROBADO")+"\",\"source_equal\":"+src+",\"dimensions_equal\":"+dims+",\"resized_equal\":"+resize+",\"target_equal\":"+target+",\"pred_equal\":"+pred+",\"zones_equal\":"+zones+",\"negative_rounding_fixed\":true,\"training_performed\":false,\"threshold_tuning_performed\":false,\"product_modified\":false\n}\n");}
static float[] Normalize(byte[]b){var r=new float[S*S*3];for(int i=0;i<S*S;i++)for(int c=0;c<3;c++)r[c*S*S+i]=((b[i*3+c]/255f)-Mean[c])/Std[c];return r;}static float Infer(InferenceSession s,float[]t){using(var i=OrtValue.CreateTensorValueFromMemory(t,new long[]{1,3,S,S}))using(var q=new RunOptions())using(var o=s.Run(q,new[]{"image"},new[]{i},new[]{"probabilities"}))return o[0].GetTensorDataAsSpan<float>()[1];}
static Z Diff(byte[]e,byte[]a){long n=0,sum=0;int max=0,first=-1;byte ev=0,av=0;for(int i=0;i<e.Length;i++){var d=Math.Abs(e[i]-a[i]);if(d>0){n++;if(first<0){first=i;ev=e[i];av=a[i];}}sum+=d;max=Math.Max(max,d);}return new Z{N=n,Mae=(double)sum/e.Length,Max=max,First=first,E=ev,A=av};}static Z Diff(float[]e,float[]a){long n=0;double sum=0;double max=0;for(int i=0;i<e.Length;i++){var d=Math.Abs(e[i]-a[i]);if(d>0)n++;sum+=d;max=Math.Max(max,d);}return new Z{N=n,Mae=sum/e.Length,Max=max,First=-1};}
static IEnumerable<A> Assets(string p,string c){return Read(p).Select(r=>new A{Sha=r["Sha256"],Cohort=c,Group=r["GroupId"],Label=r["LabelBinario"],Path=r["VisualAssetPath"]});}static List<Dictionary<string,string>>Read(string p){var z=new List<Dictionary<string,string>>();using(var q=new TextFieldParser(p,Encoding.UTF8)){q.SetDelimiters(",");q.HasFieldsEnclosedInQuotes=true;var h=q.ReadFields();while(!q.EndOfData){var f=q.ReadFields();var r=new Dictionary<string,string>();for(int i=0;i<h.Length;i++)r[h[i]]=f[i];z.Add(r);}}return z;}
static byte[] Gzip(string p){using(var f=File.OpenRead(p))using(var g=new GZipStream(f,CompressionMode.Decompress))using(var m=new MemoryStream()){g.CopyTo(m);return m.ToArray();}}static void Clean(string d,params string[]p){if(Directory.Exists(d))Directory.Delete(d,true);foreach(var x in p)if(File.Exists(x))File.Delete(x);}static byte[]Slice(byte[]b,int o,int n){var r=new byte[n];Buffer.BlockCopy(b,o,r,0,n);return r;}static float[]Floats(byte[]b,int o,int n){var r=new float[n];Buffer.BlockCopy(b,o,r,0,n*4);return r;}static byte[]Bytes(float[]f){var b=new byte[f.Length*4];Buffer.BlockCopy(f,0,b,0,b.Length);return b;}static string Hash(byte[]b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","");}
static void Write(string p,IEnumerable<string>x){File.WriteAllText(p,string.Join("\n",x)+"\n",U);}static void Write(string p,string x){File.WriteAllText(p,x,U);}static int I(string x){return int.Parse(x,CultureInfo.InvariantCulture);}static double D(string x){return double.Parse(x,CultureInfo.InvariantCulture);}static string F(double x){return x.ToString("0.#########",CultureInfo.InvariantCulture);}static string B(bool x){return x?"true":"false";}static string Pred(float p){return p>=.5?"FACTURA":"NO_FACTURA";}static string Zone(float p){return p<=TNO?"NO_FACTURA_FUERTE":p>=TYES?"FACTURA_FUERTE":"INCIERTO_VISUAL";}static double Pct(IReadOnlyList<double>x,double p){var r=(x.Count-1)*p;var l=(int)Math.Floor(r);var u=(int)Math.Ceiling(r);return x[l]+(x[u]-x[l])*(r-l);}static string Stats(IEnumerable<double>v){var x=v.OrderBy(z=>z).ToList();return "media "+F(x.Average())+", P50 "+F(Pct(x,.5))+", P95 "+F(Pct(x,.95))+", max "+F(x.Last());}
sealed class C{public int Start;public double[]D;public int[]V;}sealed class R{public int I,SW,SH,RW,RH,L,T;public string Sha,Cohort,Group,SourceHash,ResizeHash,TargetHash,TensorHash,Pred,Zone;public double Prob;}sealed class A{public string Sha,Cohort,Group,Label,Path;}sealed class Z{public long N;public double Mae,Max;public int First;public byte E,A;}sealed class X{public R R;public int W,H,RW,RH,L,T;public string SourceHash,ResizeHash,TargetHash;public byte[]Target;public float[]Tensor;public float PF;public Z ResizeDiff,TargetDiff,TensorDiff;public double Decode,Hor,Ver,Box,Norm,Onnx,Total;}
